INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l31','respond to','',NULL,'/rɪˈspɑːnd tuː/','You must respond to form in three dimensions.','你必须对三维形体作出反应。','He didn''t respond to my letter.','他没回我的信。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l31','go no further','',NULL,'/ɡoʊ noʊ ˈfɜːrðər/','Most people go no further than that.','大多数人到此为止,不再深究。','The talks went no further.','谈判没有再进展。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l31','apart from','',NULL,'/əˈpɑːrt frʌm/','Perceive the egg apart from its use as food.','把鸡蛋撇开其食物用途去感知。','Apart from you, no one knows.','除了你,没人知道。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l31','identify with','',NULL,'/aɪˈdentɪfaɪ wɪð/','He identifies himself with its centre of gravity.','他把自己代入它的重心。','I can identify with her feelings.','我能体会她的感受。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp1','choice','{"stem":"\"He thinks of the form as if he ___ holding it in his hand.\"(as if + 虚拟语气,与现在相反,be 动词用其虚拟形式)","options":["was","were","is","be"],"answer_index":1,"stem_cn":"他构想那形体,仿佛正把它握在手中。","explanation_cn":"as if + 虚拟语气,表与现在相反;be 动词一律用 were。✓ as if he were holding it. ✗ was / is / be:虚拟里 be 用 were。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp1','choice','{"stem":"\"She looked at the statue as if she ___ never seen one before.\"(as if + 虚拟,与过去相反,填与过去分词搭配构成完成体的那个词)","options":["has","have","did","had"],"answer_index":3,"stem_cn":"她盯着雕像,仿佛从没见过似的。","explanation_cn":"as if + 虚拟语气,表与过去相反,用 had + 过去分词。✓ as if she had never seen one. ✗ has / have / did:与过去相反用 had done。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp1','choice','{"stem":"\"The sculptor treats the stone as if it ___ alive.\"(as if + 虚拟,与现在相反,be 动词用其虚拟形式)","options":["was","were","are","is"],"answer_index":1,"stem_cn":"雕塑家对待石头,仿佛它是活的。","explanation_cn":"as if + 虚拟语气,表与现在相反;be 用 were。✓ as if it were alive. ✗ was / is / are:虚拟里 be 用 were。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp2','choice','{"stem":"\"___ satisfied their practical needs, most people go no further.\"(现在分词的完成式作状语,动作在前,填 have 一词的现在分词形式)","options":["Having","To have","Had","Has"],"answer_index":0,"stem_cn":"实用需要一旦满足,大多数人就不再深究。","explanation_cn":"现在分词的完成式 Having + 过去分词,表动作发生在前。✓ Having satisfied their needs, they go no further. ✗ Had / Has / To have:完成式状语用 Having done。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp2','choice','{"stem":"\"___ learned to judge distances, the child stops there.\"(现在分词的完成式作状语,填 have 一词的现在分词形式)","options":["Had","Has","Having","To have"],"answer_index":2,"stem_cn":"学会判断距离后,孩子就止步于此。","explanation_cn":"现在分词的完成式 Having + 过去分词。✓ Having learned to judge distances, the child stops. ✗ Had / Has / To have:用 Having done。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp2','choice','{"stem":"\"___ studied the form from all sides, he began to carve.\"(现在分词的完成式作状语,填 have 一词的现在分词形式)","options":["Had","Has","To have","Having"],"answer_index":3,"stem_cn":"从各个角度研究了那形体后,他才动手雕刻。","explanation_cn":"现在分词的完成式 Having + 过去分词。✓ Having studied the form, he began to carve. ✗ Had / Has / To have:用 Having done。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp3','choice','{"stem":"\"The child ___ to see first knows only flat shapes.\"(现在分词作定语,主动‘学习’,填‘学’那个动词的现在分词)","options":["learn","learning","to learn","learned"],"answer_index":1,"stem_cn":"初学看东西的孩子,起初只识得平面形状。","explanation_cn":"现在分词作定语,主动‘学习’;填‘学’那个动词的现在分词 learning。✓ the child learning to see. ✗ learned(被动/完成)/ learn / to learn:主动定语用现在分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp3','choice','{"stem":"\"A person ___ at a statue should walk all around it.\"(现在分词作定语,主动‘观看’,填‘看’那个动词的现在分词)","options":["looking","looked","look","to look"],"answer_index":0,"stem_cn":"看雕像的人,应绕着它走一圈。","explanation_cn":"现在分词作定语,主动‘观看’;填‘看’那个动词的现在分词 looking。✓ a person looking at a statue. ✗ looked / look / to look:主动定语用现在分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp3','choice','{"stem":"\"The space ___ around the shape is part of the work.\"(现在分词作定语,主动‘流动/环绕’,填‘流动’那个动词的现在分词)","options":["to flow","flow","flowing","flowed"],"answer_index":2,"stem_cn":"环绕形体流动的空间,也是作品的一部分。","explanation_cn":"现在分词作定语,主动‘流动’;填‘流动’那个动词的现在分词 flowing。✓ the space flowing around the shape. ✗ flowed / flow / to flow:主动定语用现在分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp4','choice','{"stem":"\"Sculpture is more difficult ___ the arts of flat form.\"(比较级后接的那个连词)","options":["than","that","as","then"],"answer_index":0,"stem_cn":"雕塑比平面艺术更难。","explanation_cn":"比较级后接 than,‘比…’。✓ more difficult than the arts of flat form. ✗ then(那时)/ as / that:比较用 than。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp4','choice','{"stem":"\"Many ___ people are form-blind than colour-blind.\"(‘多得多的人’,many 前加表程度的比较级词)","options":["most","much","more","very"],"answer_index":2,"stem_cn":"‘形盲’的人远比‘色盲’的多。","explanation_cn":"‘多得多的人’= many more + 名词;many 前用 more。✓ Many more people are form-blind than … ✗ most(最高级)/ much(修饰不可数)/ very:此处用 more。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp4','choice','{"stem":"\"To feel form is ___ difficult than to see color.\"(‘更难’,difficult 的比较级)","options":["very","so","most","more"],"answer_index":3,"stem_cn":"感知形体比看颜色更难。","explanation_cn":"difficult 是多音节形容词,比较级前面加 more。✓ more difficult than to see color. ✗ most(最高级)/ very / so:多音节比较级用 more。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp5','choice','{"stem":"\"He thinks of the form, ___ its size, as a whole.\"(‘无论其大小’,后接名词,填让步连词)","options":["whichever","whatever","however","whoever"],"answer_index":1,"stem_cn":"无论那形体多大,他都把它当作一个整体来想。","explanation_cn":"‘无论其大小’,后接名词 size,用 whatever。✓ whatever its size. ✗ however(后接形容词)/ whoever / whichever:后接名词用 whatever。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp5','choice','{"stem":"\"___ side he looks at, he knows what the other is like.\"(‘无论看哪一面’,后接名词,填让步连词)","options":["Whoever","Whatever","However","Whichever"],"answer_index":3,"stem_cn":"无论他看哪一面,都知道另一面是什么样。","explanation_cn":"‘无论(哪一)面’,后接名词 side,用 Whichever。✓ Whichever side he looks at. ✗ Whatever / However / Whoever:‘哪一个’中挑选用 Whichever。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp5','choice','{"stem":"\"___ hard it is, the sculptor must feel shape as shape.\"(‘无论多难’,后接形容词,填让步连词)","options":["However","Whoever","Whatever","Whichever"],"answer_index":0,"stem_cn":"无论多难,雕塑家都必须把形体当作形体来感受。","explanation_cn":"‘无论多难’,后接形容词 hard,用 However。✓ However hard it is. ✗ Whatever / Whoever / Whichever:后接形容词用 However。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp6','choice','{"stem":"\"The act of noticing or understanding through the senses is ___.\"(“感知,知觉”用哪个词)","options":["invitation","decision","collection","perception"],"answer_index":3,"stem_cn":"通过感官注意到或理解。","explanation_cn":"通过感官注意到或理解叫 perception(感知、知觉)。✓ noticing through the senses is perception. ✗ decision 决定;✗ collection 收藏;✗ invitation 邀请——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp6','choice','{"stem":"\"To form a picture of something in your mind is to ___ it.\"(“在脑中想象”用哪个词)","options":["visualize","memorize","criticize","organize"],"answer_index":0,"stem_cn":"在心里为某物构成一幅图像。","explanation_cn":"在心里为某物构成一幅图像叫 visualize(想象、构想)。✓ to form a picture in your mind is to visualize. ✗ memorize 记住;✗ criticize 批评;✗ organize 组织——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',5,'am4_l31_gp6','choice','{"stem":"\"Relating to space and the position of things in it is ___.\"(“空间的”用哪个词)","options":["magical","musical","spatial","formal"],"answer_index":2,"stem_cn":"与空间及物体在其中的位置有关的。","explanation_cn":"与空间及物体位置有关的是 spatial(空间的)。✓ relating to space is spatial. ✗ musical 音乐的;✗ magical 魔法的;✗ formal 正式的——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',6,NULL,'choice','{"stem":"perception 的意思是:","options":["感知,知觉","遗忘","想象","怀疑"],"answer_index":0,"explanation_cn":"perception = 感知、知觉。✓ accuracy in the perception of flat form."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',6,NULL,'choice','{"stem":"comprehend 的意思是:","options":["否认","拒绝","理解,领会","忽视"],"answer_index":2,"explanation_cn":"comprehend = 理解、领会。✓ to comprehend form in its full existence."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',6,NULL,'choice','{"stem":"spatial 的意思是:","options":["空间的","临时的","时间的","表面的"],"answer_index":0,"explanation_cn":"spatial = 空间的。✓ form in its full spatial existence."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',6,NULL,'choice','{"stem":"visualize 的意思是:","options":["购买","测量","触摸","(在脑中)想象,构想"],"answer_index":3,"explanation_cn":"visualize = (在脑中)想象、构想。✓ he visualizes a complex form."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',6,NULL,'choice','{"stem":"reminiscence 的意思是:","options":["命令","描述","回忆,追忆","预言"],"answer_index":2,"explanation_cn":"reminiscence = 回忆、追忆。✓ not as description or reminiscence."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',6,NULL,'choice','{"stem":"sculpture 的意思是:","options":["雕塑,雕刻","音乐","摄影","绘画"],"answer_index":0,"explanation_cn":"sculpture = 雕塑、雕刻。✓ appreciation of sculpture."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',7,NULL,'cloze','{"stem":"第 1 空","context":"To appreciate sculpture you must ___1___ to form in three dimensions. The sculptor visualizes a form as if he ___2___ holding it in his hand. ___3___ learned to judge distances, most people go no further. But the artist thinks of the whole shape, ___4___ its size.","blank_no":1,"options":["respond","listen","belong","refer"],"answer_index":0,"explanation_cn":"respond to,‘对…作出反应’。✓ must respond to form in three dimensions."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',7,NULL,'cloze','{"stem":"第 2 空","context":"To appreciate sculpture you must ___1___ to form in three dimensions. The sculptor visualizes a form as if he ___2___ holding it in his hand. ___3___ learned to judge distances, most people go no further. But the artist thinks of the whole shape, ___4___ its size.","blank_no":2,"options":["were","was","is","be"],"answer_index":0,"explanation_cn":"as if + 虚拟,与现在相反,be 用 were。✓ as if he were holding it."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',7,NULL,'cloze','{"stem":"第 3 空","context":"To appreciate sculpture you must ___1___ to form in three dimensions. The sculptor visualizes a form as if he ___2___ holding it in his hand. ___3___ learned to judge distances, most people go no further. But the artist thinks of the whole shape, ___4___ its size.","blank_no":3,"options":["Having","Had","Has","To have"],"answer_index":0,"explanation_cn":"现在分词的完成式作状语,Having + 过去分词。✓ Having learned to judge distances, most people go no further."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',7,NULL,'cloze','{"stem":"第 4 空","context":"To appreciate sculpture you must ___1___ to form in three dimensions. The sculptor visualizes a form as if he ___2___ holding it in his hand. ___3___ learned to judge distances, most people go no further. But the artist thinks of the whole shape, ___4___ its size.","blank_no":4,"options":["whatever","however","whoever","whichever"],"answer_index":0,"explanation_cn":"‘无论其大小’,后接名词,用 whatever。✓ whatever its size."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',8,NULL,'choice','{"stem":"What do you have to be able to do to appreciate sculpture?","options":["Read about the artist''s life","Touch every statue","Respond to form in three dimensions","Judge colours accurately"],"answer_index":2,"explanation_cn":"录音说:要欣赏雕塑,必须能对三维的形体作出反应。✓ respond to form in 3-D."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',8,NULL,'choice','{"stem":"Why does the speaker say sculpture is harder to appreciate than flat art?","options":["More people are ''form-blind'' than colour-blind, and 3-D form is harder to grasp","Sculpture is very old","It uses no colour at all","Statues are always very large"],"answer_index":0,"explanation_cn":"录音说:雕塑比平面艺术更难欣赏,因为‘形盲’的人比‘色盲’多,三维形体更难把握。✓ more form-blind than colour-blind."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',8,NULL,'choice','{"stem":"What must the sculptor do in his mind while working?","options":["Copy a flat drawing exactly","Think only of its use","Forget the back of the shape","Visualize the whole form from every side, knowing its mass and volume"],"answer_index":3,"explanation_cn":"录音说:雕塑家须在脑中把整个形体从各面立体地想象出来,感知其质量与体积。✓ visualize whole form."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',9,NULL,'choice','{"stem":"你想说\"他构想那形体,仿佛正把它握在手中\"(as if + 虚拟):","options":["He thinks of the form as if he holding it in his hand.","He thinks of the form as if he be holding it in his hand.","He thinks of the form as if he were holding it in his hand.","He thinks of the form as if he is holding it in his hand."],"answer_index":2,"explanation_cn":"as if 引导与现在相反的虚拟;be 动词用 were(不用 is/was)、后接现在分词 holding、不省 be 而写成 he holding、也不用原形 be。✓ as if he were holding … 场合:说“仿佛…(其实不然)”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',9,NULL,'choice','{"stem":"你想说\"实用需要一旦满足,大多数人就不再深究\"(现在分词完成式作状语):","options":["Having satisfied their practical needs, most people go no further.","Satisfied their practical needs, most people go no further.","Having satisfy their practical needs, most people go no further.","Have satisfied their practical needs, most people go no further."],"answer_index":0,"explanation_cn":"现在分词的完成式 Having + 过去分词 satisfied 作状语,表‘先满足、后不再深究’;用 Having(不用 Have)、后接过去分词 satisfied(不写原形 satisfy)、不能只用 Satisfied(那表被动)。✓ Having satisfied …, … 场合:先发生的主动动作。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',9,NULL,'choice','{"stem":"你想说\"无论那形体多大,他都把它当作整体来想\"(whatever 让步):","options":["Whatever size, he thinks of the form as a whole.","However its size, he thinks of the form as a whole.","Whatever its size is big, he thinks of the form as a whole.","Whatever its size, he thinks of the form as a whole."],"answer_index":3,"explanation_cn":"Whatever 引导‘无论…’,后接名词 its size;用 Whatever(后接名词,不用 However 后接形容词)、不加多余的 is big、也不省 its。✓ Whatever its size, … 场合:说“无论…都…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"perception 的意思是:","options":["想象","怀疑","遗忘","感知,知觉"],"answer_index":3,"explanation_cn":"perception = 感知、知觉。✓ accuracy in the perception of flat form."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"sculpture 的意思是:","options":["绘画","音乐","雕塑,雕刻","摄影"],"answer_index":2,"explanation_cn":"sculpture = 雕塑、雕刻。✓ appreciation of sculpture."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"\"He thinks of the form as if he ___ holding it in his hand.\"(as if + 虚拟,与现在相反,be 动词用其虚拟形式)","options":["is","were","was","be"],"answer_index":1,"stem_cn":"他构想那形体,仿佛正把它握在手中。","explanation_cn":"as if + 虚拟,与现在相反,be 用 were。✓ as if he were holding it. ✗ was / is / be。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"\"___ satisfied their practical needs, most people go no further.\"(现在分词的完成式作状语,动作在前)","options":["To have","Had","Having","Has"],"answer_index":2,"stem_cn":"实用需要一旦满足,大多数人就不再深究。","explanation_cn":"现在分词的完成式作状语,Having + 过去分词。✓ Having satisfied their needs, they go no further. ✗ Had / Has / To have。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"\"respond to\" 的意思是:","options":["对…作出反应/回应","逃避…","忽视…","破坏…"],"answer_index":0,"explanation_cn":"respond to = 对…作出反应、回应。✓ respond to form in three dimensions."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"\"apart from\" 的意思是:","options":["靠近…","为了…","由于…","除…之外;撇开…不谈"],"answer_index":3,"explanation_cn":"apart from = 除…之外、撇开…不谈。✓ perceive the egg apart from its use as food."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"According to the speaker, what does appreciating sculpture depend on?","options":["The ability to respond to form in three dimensions","A good memory for names","The colour of the material","The size of the statue"],"answer_index":0,"passage":"To appreciate sculpture, you must be able to respond to form in three dimensions. That is perhaps why it is often called the most difficult of all the arts — certainly harder than those that ask only for a response to flat form, to shape in two dimensions. Many more people, in truth, are ''form-blind'' than colour-blind. A child learning to see distinguishes at first only two-dimensional shape; it cannot yet judge distance or depth. Later, for the sake of its own safety and its practical needs, it learns — partly through touch — to judge three-dimensional distances roughly. But once these practical demands are met, most people go no further. Though they may attain great accuracy in the perception of flat form, they never make the further intellectual and emotional effort needed to comprehend form in its full spatial existence. This is exactly what the sculptor must do. He has to think, continually, of form in its complete spatial wholeness. He grasps the solid shape, as it were, inside his own head; he thinks of it, whatever its size, as if he were holding it entirely enclosed in the hollow of his hand. Having studied it from every side, he visualizes a complex form all round itself: while he looks at one face he already knows what the other is like; he identifies himself with its centre of gravity, its mass, its weight; he feels its volume as the space that the shape displaces in the air. The sensitive observer of sculpture must learn to do something of the same. He must feel shape simply as shape, not as description or reminiscence. He must be able, for instance, to perceive an egg as a pure, single solid — quite apart from its use as food, or from the thought that it may one day become a bird. And so with a nut, a pear, a tadpole, a mushroom, a carrot, a bud: from such simple solids he can go on to appreciate far more complex forms.","explanation_cn":"课文说:欣赏雕塑取决于对三维形体作出反应的能力。✓ respond to 3-D form."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"How does the sculptor think of a form while working?","options":["Only by its usefulness","Only from the front","As a whole, visualizing every side and feeling its mass and volume","Only as a flat picture"],"answer_index":2,"passage":"To appreciate sculpture, you must be able to respond to form in three dimensions. That is perhaps why it is often called the most difficult of all the arts — certainly harder than those that ask only for a response to flat form, to shape in two dimensions. Many more people, in truth, are ''form-blind'' than colour-blind. A child learning to see distinguishes at first only two-dimensional shape; it cannot yet judge distance or depth. Later, for the sake of its own safety and its practical needs, it learns — partly through touch — to judge three-dimensional distances roughly. But once these practical demands are met, most people go no further. Though they may attain great accuracy in the perception of flat form, they never make the further intellectual and emotional effort needed to comprehend form in its full spatial existence. This is exactly what the sculptor must do. He has to think, continually, of form in its complete spatial wholeness. He grasps the solid shape, as it were, inside his own head; he thinks of it, whatever its size, as if he were holding it entirely enclosed in the hollow of his hand. Having studied it from every side, he visualizes a complex form all round itself: while he looks at one face he already knows what the other is like; he identifies himself with its centre of gravity, its mass, its weight; he feels its volume as the space that the shape displaces in the air. The sensitive observer of sculpture must learn to do something of the same. He must feel shape simply as shape, not as description or reminiscence. He must be able, for instance, to perceive an egg as a pure, single solid — quite apart from its use as food, or from the thought that it may one day become a bird. And so with a nut, a pear, a tadpole, a mushroom, a carrot, a bud: from such simple solids he can go on to appreciate far more complex forms.","explanation_cn":"课文说:雕塑家把形体当作整体,在脑中想象每一面,感知其质量与体积。✓ whole form, all sides."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"What must the sensitive observer learn to feel?","options":["The price of the sculpture","Shape simply as shape, apart from what the object is used for","Only the colour of the object","The name of the sculptor"],"answer_index":1,"audio":"To appreciate sculpture, you must be able to respond to form in three dimensions. That is perhaps why it is often called the most difficult of all the arts — certainly harder than those that ask only for a response to flat form, to shape in two dimensions. Many more people, in truth, are ''form-blind'' than colour-blind. A child learning to see distinguishes at first only two-dimensional shape; it cannot yet judge distance or depth. Later, for the sake of its own safety and its practical needs, it learns — partly through touch — to judge three-dimensional distances roughly. But once these practical demands are met, most people go no further. Though they may attain great accuracy in the perception of flat form, they never make the further intellectual and emotional effort needed to comprehend form in its full spatial existence. This is exactly what the sculptor must do. He has to think, continually, of form in its complete spatial wholeness. He grasps the solid shape, as it were, inside his own head; he thinks of it, whatever its size, as if he were holding it entirely enclosed in the hollow of his hand. Having studied it from every side, he visualizes a complex form all round itself: while he looks at one face he already knows what the other is like; he identifies himself with its centre of gravity, its mass, its weight; he feels its volume as the space that the shape displaces in the air. The sensitive observer of sculpture must learn to do something of the same. He must feel shape simply as shape, not as description or reminiscence. He must be able, for instance, to perceive an egg as a pure, single solid — quite apart from its use as food, or from the thought that it may one day become a bird. And so with a nut, a pear, a tadpole, a mushroom, a carrot, a bud: from such simple solids he can go on to appreciate far more complex forms.","explanation_cn":"课文说:敏感的观赏者须把形体单纯当作形体来感受,撇开它的用途。✓ shape as shape."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l31',10,NULL,'choice','{"stem":"Why are many people ''form-blind,'' according to the speaker?","options":["They were never taught to read","They dislike all art","They never make the effort to grasp form in its full three-dimensional existence","They cannot see at all"],"answer_index":2,"audio":"To appreciate sculpture, you must be able to respond to form in three dimensions. That is perhaps why it is often called the most difficult of all the arts — certainly harder than those that ask only for a response to flat form, to shape in two dimensions. Many more people, in truth, are ''form-blind'' than colour-blind. A child learning to see distinguishes at first only two-dimensional shape; it cannot yet judge distance or depth. Later, for the sake of its own safety and its practical needs, it learns — partly through touch — to judge three-dimensional distances roughly. But once these practical demands are met, most people go no further. Though they may attain great accuracy in the perception of flat form, they never make the further intellectual and emotional effort needed to comprehend form in its full spatial existence. This is exactly what the sculptor must do. He has to think, continually, of form in its complete spatial wholeness. He grasps the solid shape, as it were, inside his own head; he thinks of it, whatever its size, as if he were holding it entirely enclosed in the hollow of his hand. Having studied it from every side, he visualizes a complex form all round itself: while he looks at one face he already knows what the other is like; he identifies himself with its centre of gravity, its mass, its weight; he feels its volume as the space that the shape displaces in the air. The sensitive observer of sculpture must learn to do something of the same. He must feel shape simply as shape, not as description or reminiscence. He must be able, for instance, to perceive an egg as a pure, single solid — quite apart from its use as food, or from the thought that it may one day become a bird. And so with a nut, a pear, a tadpole, a mushroom, a carrot, a bud: from such simple solids he can go on to appreciate far more complex forms.","explanation_cn":"课文说:多数人满足实用需要后就不再努力去把握三维形体,故成‘形盲’。✓ no further effort."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
